const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(140.878144, 27.245974);
    const aoi = point.buffer(2000); // 2 km radius
    const startDate = '2014-03-01';
    const endDate = '2014-03-31';

    // 2. Data Acquisition & Pre-processing
    // Function to mask clouds using the QA_PIXEL band of Landsat 8 SR
    const maskL8sr = (image) => {
        // Bits 3, 4, and 5 are cloud shadow, cloud, and cloud confidence.
        const cloudShadowBitMask = (1 << 3);
        const cloudsBitMask = (1 << 5);
        const qa = image.select('QA_PIXEL');
        // Both flags should be set to zero, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
        return image.updateMask(mask);
    };

    const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(aoi)
        .filterDate(startDate, endDate);

    const collectionSize = l8Collection.size().getInfo();
    if (collectionSize === 0) {
        console.log('Evidence: No Landsat 8 images found for the specified date and location.');
        console.log('A: No');
        return;
    }

    const maskedCollection = l8Collection.map(maskL8sr);
    const composite = maskedCollection.median().clip(aoi);

    // 3. Land/Water Classification
    // NDWI = (Green - NIR) / (Green + NIR)
    // Landsat 8 SR: Green = SR_B3, NIR = SR_B5
    const ndwi = composite.normalizedDifference(['SR_B3', 'SR_B5']).rename('ndwi');
    const land = ndwi.lte(0); // Land is typically <= 0

    // Check if there are any valid land pixels after masking
    const landPixelCount = land.mask(land).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 30,
        maxPixels: 1e9
    }).get('ndwi').getInfo();

    console.log(`Evidence: Found ${collectionSize} images in March 2014.`);
    console.log(`Evidence: Valid land pixel count after cloud/water masking: ${landPixelCount}`);

    if (landPixelCount === null || landPixelCount === 0) {
        console.log('Evidence: No valid land pixels found after cloud and water masking.');
        console.log('B: No');
        return;
    }

    // 4. Island Counting
    // Use connectedComponents to identify contiguous land patches
    const connections = land.connectedComponents({
        connectedness: ee.Kernel.plus(1),
        maxSize: 1024
    });

    // Count the number of distinct labels (islands)
    const islandCountDict = connections.select('labels').reduceRegion({
        reducer: ee.Reducer.countDistinct(),
        geometry: aoi,
        scale: 30,
        maxPixels: 1e9
    });

    const islandCount = islandCountDict.get('labels').getInfo();

    if (islandCount === null) {
        console.log('Evidence: Island counting failed; result is null.');
        console.log('C3: Calculation Failure');
        return;
    }

    // 5. Validation & Final Answer
    console.log(`Evidence: Identified ${islandCount} distinct landmass(es).`);

    if (islandCount === 2) {
        console.log('A: Yes');
    } else {
        console.log('B: No');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
